"""Collect the one live branch back into a single value, without blockers.

`QQ-条件分发` blocks the ports it did not pick with an ``ExecutionBlocker``,
and ComfyUI propagates that blocker into every node that reads one of those
ports - including a plain join node, which then never runs at all.

Lazy inputs are the way around it: ``check_lazy_status`` asks for exactly one
input, so ComfyUI only evaluates that branch.  The blocked branches are never
evaluated, so they never produce a blocker in the first place, and their
upstream nodes (prompt enhancers, paid APIs, ...) are never called.
"""

from __future__ import annotations

import logging
from typing import Any

try:  # ExecutionBlocker 只在较新的 ComfyUI 提供
    from comfy_execution.graph import ExecutionBlocker
except Exception:  # pragma: no cover - 只在没有 ComfyUI 运行时的测试里发生
    ExecutionBlocker = None


MAX_INPUTS = 8
FIRST_INPUT_NAME = "输入1"
DISPATCH_NODE_TYPE = "QQRouteDispatch"


def _input_names() -> tuple[str, ...]:
    return tuple(f"输入{index + 1}" for index in range(MAX_INPUTS))


def _blocker(message: str | None = None) -> Any:
    if ExecutionBlocker is None:
        return None
    return ExecutionBlocker(message)


def _numeric_index(choice: str) -> int | None:
    digits = choice
    for prefix in ("输入", "value", "Value", "VALUE", "output", "Output", "输出"):
        if digits.startswith(prefix):
            digits = digits[len(prefix) :].strip()
            break
    if not digits.isdigit():
        return None
    index = int(digits) - 1
    return index if 0 <= index < MAX_INPUTS else None


def _workflow_input_entries(unique_id: Any, extra_pnginfo: Any) -> list[dict[str, Any]]:
    """Node's own input slot dicts from the workflow, in slot order."""
    if extra_pnginfo is None or unique_id is None:
        return []
    try:
        nodes = extra_pnginfo.get("workflow", {}).get("nodes", []) or []
    except AttributeError:
        return []
    for node in nodes:
        if not isinstance(node, dict) or str(node.get("id")) != str(unique_id):
            continue
        inputs = node.get("inputs") or []
        return [entry for entry in inputs if isinstance(entry, dict)]
    return []


def _workflow_node(extra_pnginfo: Any, node_id: Any) -> dict[str, Any] | None:
    if extra_pnginfo is None or node_id is None:
        return None
    try:
        nodes = extra_pnginfo.get("workflow", {}).get("nodes", []) or []
    except AttributeError:
        return None
    for node in nodes:
        if isinstance(node, dict) and str(node.get("id")) == str(node_id):
            return node
    return None


def _widget_value(node: dict[str, Any], name: str) -> Any:
    """读工作流存档里某个控件值（widgets_values 是纯数组，靠控件顺序对位）。"""
    widgets = node.get("widgets_values")
    if isinstance(widgets, dict):
        return widgets.get(name)
    if not isinstance(widgets, list):
        return None
    # QQ-条件分发 的控件顺序固定为 [轮询输出, select]
    if name == "select" and len(widgets) >= 2:
        return widgets[1]
    return widgets[0] if widgets else None


def _upstream_dispatch_select(
    unique_id: Any, extra_pnginfo: Any, max_depth: int = 6
) -> str | None:
    """顺着连线往上找 QQ-条件分发，取出它的 select 值。

    收集节点的每个输入通常接的是增强器，而增强器再接到分发；所以要一层层回溯。
    遇到分发就取它当前的选择。
    """
    seen: set[str] = set()
    frontier = [unique_id]
    for _ in range(max_depth):
        next_frontier: list[Any] = []
        for node_id in frontier:
            key = str(node_id)
            if key in seen:
                continue
            seen.add(key)
            for entry in _value_slots(node_id, extra_pnginfo):
                link_id = entry.get("link")
                if link_id is None:
                    continue
                source_id = _link_origin(extra_pnginfo, link_id)
                if source_id is None:
                    continue
                source = _workflow_node(extra_pnginfo, source_id)
                if not source:
                    continue
                if source.get("type") == DISPATCH_NODE_TYPE:
                    value = _widget_value(source, "select")
                    if isinstance(value, str) and value.strip():
                        return value.strip()
                next_frontier.append(source_id)
        if not next_frontier:
            break
        frontier = next_frontier
    return None


def _link_origin(extra_pnginfo: Any, link_id: Any) -> Any:
    """在工作流存档里按 link id 找来源节点 id。"""
    if extra_pnginfo is None:
        return None
    try:
        links = extra_pnginfo.get("workflow", {}).get("links", []) or []
    except AttributeError:
        return None
    for link in links:
        # 存档格式：[id, origin_id, origin_slot, target_id, target_slot, type]
        if isinstance(link, list) and len(link) >= 5 and str(link[0]) == str(link_id):
            return link[1]
    return None


def resolve_pick_index(select: Any, unique_id: Any = None, extra_pnginfo: Any = None) -> int:
    """决定这次取哪一路：手填的值优先，留空则跟随上游分发节点。"""
    choice = str(select if select is not None else "").strip()
    if not choice:
        upstream = _upstream_dispatch_select(unique_id, extra_pnginfo)
        if upstream:
            # 分发用「输出N」，这里换成同序号的输入口
            digits = upstream
            for prefix in ("输出", "output", "Output", "OUTPUT"):
                if digits.startswith(prefix):
                    digits = digits[len(prefix) :].strip()
                    break
            numeric = _numeric_index(digits)
            if numeric is not None:
                return numeric
            choice = upstream
    return resolve_input_index(choice, unique_id, extra_pnginfo)


def _value_slots(unique_id: Any, extra_pnginfo: Any) -> list[dict[str, Any]]:
    """只保留真正的取值口，跳过 select 这类控件占用的槽位。

    select 是 STRING 控件，在存档里也会占一个 input 槽，但链接上叫 widget；
    不排掉它，后面所有口的序号都会整体偏移一位。
    """
    slots = []
    for entry in _workflow_input_entries(unique_id, extra_pnginfo):
        if entry.get("widget"):
            continue
        name = str(entry.get("name") or "")
        if name == "select":
            continue
        slots.append(entry)
    return slots


def resolve_input_index(select: Any, unique_id: Any = None, extra_pnginfo: Any = None) -> int:
    """把选择框的值解析成 0 起的输入口序号。

    认重命名后的 label、默认口名 ``输入N`` 和纯数字 ``N``；对不上就退回第一个口。
    """
    choice = str(select if select is not None else "").strip()
    entries = _value_slots(unique_id, extra_pnginfo)

    for index, entry in enumerate(entries):
        for key in ("label", "localized_name", "name"):
            value = entry.get(key)
            if isinstance(value, str) and value.strip() == choice and value.strip():
                return index

    for index in range(MAX_INPUTS):
        if choice == f"输入{index + 1}":
            return index

    numeric = _numeric_index(choice)
    if numeric is not None:
        return numeric

    logging.warning("QQRouteCollect: 选择框的值 %r 对不上任何输入口，改用第一个输入", select)
    return 0


class QQRouteCollect:
    CATEGORY = "QQ/工具"
    FUNCTION = "collect"
    RETURN_TYPES = ("*",)
    RETURN_NAMES = ("value",)
    DESCRIPTION = (
        "把选中的那一路输入取出来送到唯一输出。输入是惰性求值的：只有被选中的那一路"
        "会被真正执行，其余分支既不执行也不产生阻塞，所以上游的提示词增强器只会跑一次。"
        "配合「QQ-条件分发」使用，选择框会自动跟随同一条链路上的分发节点。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        optional: dict[str, Any] = {}
        for index in range(MAX_INPUTS):
            optional[f"value{index + 1}"] = ("*", {"lazy": True})
        return {
            "required": {
                # 留空 = 自动跟随上游 QQ-条件分发 的选择；填了就按填的走
                "select": ("STRING", {"default": "", "multiline": False}),
            },
            "optional": optional,
            "hidden": {"unique_id": "UNIQUE_ID", "extra_pnginfo": "EXTRA_PNGINFO"},
        }

    @classmethod
    def VALIDATE_INPUTS(cls, select="", **kwargs):
        # 选择值是自由文本（可留空自动跟随），输入口本身由前端动态增减。
        return True

    @classmethod
    def check_lazy_status(
        cls,
        select: Any = "",
        unique_id: Any = None,
        extra_pnginfo: Any = None,
        **_kwargs: Any,
    ):
        """只请求选中那一路：其余分支因此完全不会被求值。"""
        index = resolve_pick_index(select, unique_id, extra_pnginfo)
        return [f"value{index + 1}"]

    @staticmethod
    def collect(
        select: Any = "",
        unique_id: Any = None,
        extra_pnginfo: Any = None,
        **values: Any,
    ):
        index = resolve_pick_index(select, unique_id, extra_pnginfo)
        name = f"value{index + 1}"
        value = values.get(name)
        # 选中的口没接线：交出阻塞，让下游明确停下，而不是拿 None 硬跑
        if value is None or (ExecutionBlocker is not None and isinstance(value, ExecutionBlocker)):
            logging.warning("QQRouteCollect: 选中的输入口 %s 没有内容", name)
            return (_blocker(),)
        return (value,)


NODE_CLASS_MAPPINGS = {"QQRouteCollect": QQRouteCollect}
NODE_DISPLAY_NAME_MAPPINGS = {"QQRouteCollect": "QQ-条件收集"}
